def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append([color, cells])
    out = [[0] * w for _ in range(h)]
    # Slide each rigid component rightward; settle the rightmost components first.
    comps.sort(key=lambda obj: max(c for _, c in obj[1]), reverse=True)
    settled = []
    for color, cells in comps:
        cells = list(cells)
        while True:
            targets = [(r, c + 1) for r, c in cells]
            if any(c + 1 >= w for r, c in cells):
                break
            occupied = {(r, c) for _, other in settled for r, c in other}
            if any(pos in occupied for pos in targets):
                break
            cells = targets
        settled.append((color, cells))
    for color, cells in settled:
        for r, c in cells:
            out[r][c] = color
    return out
